-- FEC zombie-shaped committees, top 25 by 2024-cycle spending: every cycle in the candidate summary table (is it a one-time wind-down or a steady drain?)
SELECT CAND_ID, CYCLE, MAX(CAND_NAME) nm, MAX(INCUMBENT_CHALLENGER) ic, SUM(TRY_TO_DOUBLE(TTL_RECEIPTS::varchar)) rec, SUM(TRY_TO_DOUBLE(TTL_INDIV_CONTRIB::varchar)) indiv,
       SUM(TRY_TO_DOUBLE(TTL_DISB::varchar)) disb, SUM(TRY_TO_DOUBLE(CASH_ON_HAND_CLOSE::varchar)) coh, MAX(COVERAGE_END_DATE::varchar) cvg, COUNT(*) n
FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_CANDIDATE_SUMMARY WHERE CAND_ID IN ('S0SC00289','H2SC06019','S0ME00111','S0NJ00068','S6SD00051','P00016741','H6MN06074','H8FL06056','H0MA04242','H6MA08141','S0NC00202','H8IL21021','S8MS00287','H4FL16021','S0CO00468','H4OK02089','S0AK00121','H6TX02095','H6WA05023','H0MN03124','S0TX00233','H2IN06023','P00006486','H6CA24048','S0IN00061') GROUP BY 1, 2 ORDER BY 1, 2